Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_vector_to_string_successful_conversion(void) {
    // Setup: create a non-empty vector
    Vector* vec = helper_create_vector(0);
    TEST_ASSERT_NOT_NULL(vec);

    // Fill vector with some elements
    int values[] = {1, 2, 3};
    int fill_result = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    // Create a buffer large enough for the string representation
    // "[ 1 2 3 ]" is 9 characters + null terminator = 10 bytes
    // We'll use a larger buffer to ensure no overflow
    char buffer[50];
    int buffer_size = sizeof(buffer);

    // Test: call vector_to_string
    int result = vector_to_string(vec, buffer, buffer_size);

    // Assertions
    // Path 4 conditions: all parameters valid, all snprintf calls succeed
    // Expected written characters: "[ 1 2 3 ]" = 9 characters
    TEST_ASSERT_EQUAL_INT(9, result);

    // Verify the buffer contains the expected string
    // Note: vector_to_string does NOT null-terminate, so we need to be careful
    // We'll manually null-terminate for comparison
    buffer[result] = '\0';
    TEST_ASSERT_EQUAL_STRING("[ 1 2 3 ]", buffer);

    // Cleanup
    if (vec != NULL) {
        helper_cleanup_vector(vec);
    }
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_vector_to_string_successful_conversion);
    return UNITY_END();
}

